<?php
namespace App\Modules\CashManagement\Domain\Models;
use App\Models\User;use App\Modules\CashManagement\Domain\Enums\CashSessionStatus;use App\Modules\Finance\Domain\Models\FinancialAccount;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
#[Fillable(['financial_account_id','opened_by','opened_at','opening_amount','expected_closing_amount','counted_closing_amount','difference_amount','difference_reason','closed_by','closed_at','status','authorization_request_id'])]
class CashSession extends Model {use HasUlids;public function account():BelongsTo{return $this->belongsTo(FinancialAccount::class,'financial_account_id');}public function opener():BelongsTo{return $this->belongsTo(User::class,'opened_by');}public function closer():BelongsTo{return $this->belongsTo(User::class,'closed_by');}public function authorization():BelongsTo{return $this->belongsTo(AuthorizationRequest::class,'authorization_request_id');}protected function casts():array{return ['opened_at'=>'datetime','closed_at'=>'datetime','opening_amount'=>'integer','expected_closing_amount'=>'integer','counted_closing_amount'=>'integer','difference_amount'=>'integer','status'=>CashSessionStatus::class];}}
